pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains data", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("data");
});

pm.test("Response contains generated content", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data).to.have.property("content");
});

pm.test("Generated content is not empty", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data.content).to.not.be.empty;
});

pm.test("Response message exists", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("message");
});

pm.test("Response content is a string", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data.content).to.be.a("string");
});

pm.test("Correct model is returned", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.data.model).to.eql("zai-org/GLM-5.2");
});

